public class Issue85_insert_a_value_in_a_list { public static void main(String[] args) { int[] v=new int[]{7, -6, 15, 1}; int pos=2, value=13; int[] result=new int[v.length+1]; for(int i=0;i<v.length;i++) result[i]=v[i]; result[pos]=value; for(int i=0;i<result.length;i++) System.out.print(result[i]+(i==result.length-1?"":" ")); } }
